1	import { component$, useStore, useVisibleTask$, $ } from "@builder.io/qwik";
2	import { Link } from "@builder.io/qwik-city";
3	import { useConvexClient } from "../../utils/convex-context";
4	import { api } from "../../../convex/_generated/api";
5	import type { ProjectBrief } from "../../types";
6	import { loadDraftText, summarizeBrief } from "../../utils/anti-tabula-rasa";
7	import {
8	  scoreStaticFeatures,
9	  scoreSufficiency,
10	  combineJudgesAndStatic,
11	  type StaticScore,
12	  type JudgeResult,
13	} from "../../utils/rubric";
14	import {
15	  loadRubricResultFromIdb,
16	  saveRubricResultToIdb,
17	  loadAiSettingsFromIdb,
18	} from "../../utils/idb";
19	import type { AiSettings } from "../../types";
20	import {
21	  hasConfiguredAiProvider,
22	  runClientJudge,
23	  runClientEvidenceJudge,
24	  runClientIntegrityJudge,
25	  runClientRubricReview,
26	  normalizeAiSettings,
27	} from "../../utils/ai-client";
28	import { draftReadiness, MIN_RUBRIC_WORDS } from "../../utils/draft-thresholds";
29	import { renderMarkdown } from "../../utils/markdown";
30	import { ApplicationNotice } from "../ui/application-notice";
31	import type { AppError } from "../../types/application-errors";
32	import {
33	  createAppError,
34	  normalizeApplicationError,
35	} from "../../utils/application-errors";
36	
37	interface RubricStore {
38	  result: RubricResult | null;
39	  isAnalyzing: boolean;
40	  isReviewing: boolean;
41	  error: AppError | null;
42	  judges: JudgeResult[];
43	  static: StaticScore | null;
44	  brief: ProjectBrief | null;
45	  aiSettings: AiSettings | null;
46	}
47	
48	interface RubricCriterion {
49	  id: string;
50	  label: string;
51	  description: string;
52	  score: number;
53	  maxScore: number;
54	  feedback: string;
55	}
56	
57	interface RubricResult {
58	  criteria: RubricCriterion[];
59	  overallScore: number;
60	  overallGrade: string;
61	  summary: string;
62	  timestamp: number;
63	  judges: JudgeResult[];
64	  staticScore: StaticScore;
65	  review?: string;
66	  reviewProvider?: string;
67	}
68	
69	interface RubricPanelProps {
70	  brief: ProjectBrief | null;
71	}
72	
73	export const RubricPanel = component$(({ brief }: RubricPanelProps) => {
74	  const clientSig = useConvexClient();
75	  const store = useStore<RubricStore>({
76	    result: null,
77	    isAnalyzing: false,
78	    isReviewing: false,
79	    error: null,
80	    judges: [],
81	    static: null,
82	    brief: null,
83	    aiSettings: null,
84	  });
85	
86	  const analyze = $(async () => {
87	    store.isAnalyzing = true;
88	    store.error = null;
89	    try {
90	      const draftText = await loadDraftText();
91	      const client = clientSig.value;
92	      const readiness = draftReadiness(draftText, MIN_RUBRIC_WORDS);
93	      if (!readiness.ok) {
94	        store.static = scoreStaticFeatures(draftText);
95	        store.judges = [];
96	        store.result = null;
97	        store.error = createAppError("VALIDATION_FAILED", {
98	          metadata: { feature: "rubric", operation: "analyze" },
99	        });
100	        return;
101	      }
102	
103	      // 1. Run the static-feature scorer in the browser (cheap, deterministic).
104	      const staticScore = scoreStaticFeatures(draftText);
105	      store.static = staticScore;
106	
107	      // 2. Run the five personas as judges. Try client AI first (BYOK),
108	      //    then Convex server action, then local heuristic.
109	      let judges: JudgeResult[] = [];
110	
111	      const settings = store.aiSettings;
112	      if (hasConfiguredAiProvider(settings) && settings) {
113	        try {
114	          const personas = defaultPersonas();
115	          const tasks = personas.map(async (p) => {
116	            const res = await runClientJudge(
117	              {
118	                persona: {
119	                  id: p.id,
120	                  name: p.name,
121	                  role: p.role,
122	                  description: p.description,
123	                  focus: p.focus,
124	                  color: p.color,
125	                  icon: p.icon,
126	                },
127	                brief: brief ?? null,
128	                draftText,
129	                instruction: "feedback",
130	              },
131	              settings,
132	            );
133	            return {
134	              personaId: p.id,
135	              score: res?.score ?? 5,
136	              rationale:
137	                res?.rationale ??
138	                "The draft is partial; the work to come is the interesting part.",
139	              provider: res ? `client-${res.provider}` : "local",
140	            } as JudgeResult;
141	          });
142	          judges = await Promise.all(tasks);
143	        } catch (error) {
144	          store.error = normalizeApplicationError(error, {
145	            source: "provider",
146	            metadata: { feature: "rubric", operation: "judge-room" },
147	          });
148	        }
149	      }
150	
151	      if (judges.length === 0 && client) {
152	        try {
153	          const personasForServer = defaultPersonas().map((p) => ({
154	            id: p.id,
155	            name: p.name,
156	            role: p.role,
157	            description: p.description,
158	            focus: p.focus,
159	            color: p.color,
160	            icon: p.icon,
161	          }));
162	          judges = (await client.action(api.agents.judgeRoom, {
163	            personas: personasForServer,
164	            brief: brief ?? null,
165	            draftText,
166	          })) as JudgeResult[];
167	        } catch (error) {
168	          store.error = normalizeApplicationError(error, {
169	            source: "convex",
170	            metadata: { feature: "rubric", operation: "judge-room" },
171	          });
172	          return;
173	        }
174	      }
175	
176	      if (judges.length === 0) {
177	        store.error = createAppError(
178	          hasConfiguredAiProvider(settings)
179	            ? "PROVIDER_ERROR"
180	            : "CONFIGURATION_ERROR",
181	          {
182	            source: hasConfiguredAiProvider(settings)
183	              ? "provider"
184	              : "application",
185	            recovery: {
186	              action: hasConfiguredAiProvider(settings)
187	                ? "retry"
188	                : "choose-provider",
189	              canRetry: hasConfiguredAiProvider(settings),
190	            },
191	            metadata: { feature: "rubric", operation: "judge-room" },
192	          },
193	        );
194	        return;
195	      }
196	      if (judges.every((j) => j.provider === "local")) {
197	        store.error = createAppError("PROVIDER_ERROR", {
198	          source: "provider",
199	          metadata: { feature: "rubric", operation: "judge-room" },
200	        });
201	        return;
202	      }
203	      store.judges = judges;
204	
205	      // 2b. A dedicated LLM judge for content sufficiency vs the stated
206	      //     goal — falls back to the keyword heuristic when offline/signed out.
207	      const localSufficiency = () => {
208	        const s = scoreSufficiency(draftText, brief?.answers.goal ?? null);
209	        return { score: s.score, rationale: s.feedback };
210	      };
211	      let sufficiency: { score: number; rationale: string };
212	      try {
213	        sufficiency = client
214	          ? ((await client.action(api.agents.judgeSufficiency, {
215	              brief: brief ?? null,
216	              draftText,
217	            })) as { score: number; rationale: string })
218	          : localSufficiency();
219	      } catch {
220	        sufficiency = localSufficiency();
221	      }
222	
223	      // 2c. Dedicated LLM judges for evidence & integrity when we can
224	      //     reach one. These catch what the static regex/density scorers
225	      //     miss — padded citations, fake specificity, sophisticated
226	      //     bullshit, legitimate emphatic prose flagged as filler.
227	      const settings2 = store.aiSettings;
228	
229	      const localEvidence = () => {
230	        const f = scoreStaticFeatures(draftText).features;
231	        const density = f.citationDensity;
232	        const score =
233	          f.citationCount === 0
234	            ? f.paragraphCount > 0
235	              ? 3
236	              : 1
237	            : density >= 1.5 && density <= 6
238	              ? 7
239	              : density < 1.5
240	                ? 5
241	                : 4;
242	        const audience = brief?.answers.audience || "the intended reader";
243	        return {
244	          score,
245	          rationale: `${f.citationCount} citation-like reference${
246	            f.citationCount === 1 ? "" : "s"
247	          } (${density.toFixed(
248	            1,
249	          )} per 1,000 words). Counts shape, not substance — judge locally only. For ${audience}, evidence has to earn its claim.`,
250	        };
251	      };
252	
253	      const localIntegrity = () => {
254	        const f = scoreStaticFeatures(draftText).features;
255	        const deduction =
256	          f.unsupportedUniversalClaimCount * 0.6 +
257	          f.duplicateParagraphRatio * 60;
258	        const score =
259	          deduction > 0 ? Math.max(1, 10 - Math.round(deduction)) : 7;
260	        return {
261	          score,
262	          rationale: `${f.unsupportedUniversalClaimCount} unsupported universal claim${
263	            f.unsupportedUniversalClaimCount === 1 ? "" : "s"
264	          }, ${(f.fillerWordRatio * 100).toFixed(1)}% filler, ${(
265	            f.vagueWordRatio * 100
266	          ).toFixed(1)}% vague wording, ${(
267	            f.duplicateParagraphRatio * 100
268	          ).toFixed(
269	            0,
270	          )}% duplicated paragraphs. Regex misses sophisticated bullshit and false-positives on legitimate emphatic prose.`,
271	        };
272	      };
273	
274	      let evidence: { score: number; rationale: string; provider?: string };
275	      try {
276	        const clientRes = settings2
277	          ? await runClientEvidenceJudge(
278	              { brief: brief ?? null, draftText },
279	              settings2,
280	            )
281	          : null;
282	        if (clientRes) {
283	          evidence = clientRes;
284	        } else if (client) {
285	          const serverRes = (await client.action(api.agents.judgeEvidence, {
286	            brief: brief ?? null,
287	            draftText,
288	          })) as { score: number; rationale: string; provider: string } | null;
289	          evidence = serverRes ?? localEvidence();
290	        } else {
291	          evidence = localEvidence();
292	        }
293	      } catch {
294	        evidence = localEvidence();
295	      }
296	
297	      let integrity: { score: number; rationale: string; provider?: string };
298	      try {
299	        const clientRes = settings2
300	          ? await runClientIntegrityJudge(
301	              { brief: brief ?? null, draftText },
302	              settings2,
303	            )
304	          : null;
305	        if (clientRes) {
306	          integrity = clientRes;
307	        } else if (client) {
308	          const serverRes = (await client.action(api.agents.judgeIntegrity, {
309	            brief: brief ?? null,
310	            draftText,
311	          })) as { score: number; rationale: string; provider: string } | null;
312	          integrity = serverRes ?? localIntegrity();
313	        } else {
314	          integrity = localIntegrity();
315	        }
316	      } catch {
317	        integrity = localIntegrity();
318	      }
319	
320	      // 3. Combine into a brutal grade.
321	      const combined = combineJudgesAndStatic(judges, staticScore, brief);
322	      const criteria = buildCriteria(
323	        staticScore,
324	        judges,
325	        combined.combined,
326	        brief,
327	        sufficiency,
328	        evidence,
329	        integrity,
330	      );
331	
332	      const result: RubricResult = {
333	        criteria,
334	        overallScore: combined.combined,
335	        overallGrade: combined.grade,
336	        summary: combined.summary,
337	        timestamp: Date.now(),
338	        judges,
339	        staticScore,
340	      };
341	      store.result = result;
342	      void saveRubricResultToIdb(result);
343	    } finally {
344	      store.isAnalyzing = false;
345	    }
346	  });
347	
348	  const generateReview = $(async () => {
349	    const result = store.result;
350	    if (!result || store.isReviewing) return;
351	    store.isReviewing = true;
352	    store.error = null;
353	    try {
354	      const draftText = await loadDraftText();
355	      const combined = combineJudgesAndStatic(
356	        result.judges,
357	        result.staticScore,
358	        brief ?? null,
359	      );
360	      const payload = {
361	        combined: result.overallScore,
362	        grade: result.overallGrade,
363	        judgeMean: combined.judgeMean,
364	        minJudge: combined.minJudge,
365	        staticTotal: combined.staticTotal,
366	        judges: result.judges.map((j) => ({
367	          personaId: j.personaId,
368	          score: j.score,
369	          rationale: j.rationale,
370	        })),
371	        staticFeedback: result.staticScore.feedback,
372	      };
373	
374	      let review = "";
375	      let reviewProvider = "local";
376	      const settings = store.aiSettings;
377	      if (hasConfiguredAiProvider(settings) && settings) {
378	        const res = await runClientRubricReview(
379	          { ...payload, brief: brief ?? null, draftText },
380	          settings,
381	        );
382	        if (res) {
383	          review = res.text;
384	          reviewProvider = `client-${res.provider}`;
385	        }
386	      }
387	      if (!review && clientSig.value) {
388	        const res = (await clientSig.value.action(api.agents.reviewRubric, {
389	          ...payload,
390	          brief: brief ?? null,
391	          draftText,
392	        })) as { review: string; provider: string };
393	        review = res.review;
394	        reviewProvider = res.provider;
395	      }
396	
397	      if (review) {
398	        const updated: RubricResult = { ...result, review, reviewProvider };
399	        store.result = updated;
400	        void saveRubricResultToIdb(updated);
401	      } else {
402	        store.error = createAppError("CONFIGURATION_ERROR", {
403	          recovery: { action: "choose-provider", canRetry: false },
404	          metadata: { feature: "rubric", operation: "review" },
405	        });
406	      }
407	    } catch (error) {
408	      store.error = normalizeApplicationError(error, {
409	        metadata: { feature: "rubric", operation: "review" },
410	      });
411	    } finally {
412	      store.isReviewing = false;
413	    }
414	  });
415	
416	  // eslint-disable-next-line qwik/no-use-visible-task
417	  useVisibleTask$(async () => {
418	    const cached = await loadRubricResultFromIdb();
419	    if (cached && !store.result) {
420	      store.result = cached;
421	      store.judges = cached.judges ?? [];
422	      store.static = cached.staticScore ?? null;
423	    }
424	    const aiRaw = await loadAiSettingsFromIdb();
425	    store.aiSettings = normalizeAiSettings(aiRaw);
426	  });
427	
428	  const getScoreColor = (score: number, max: number) => {
429	    const pct = score / max;
430	    if (pct >= 0.8) return "var(--color-accent-green)";
431	    if (pct >= 0.6) return "var(--color-accent-amber)";
432	    return "var(--color-accent-red)";
433	  };
434	
435	  const getGradeColor = (grade: string) => {
436	    if (grade.startsWith("A")) return "text-[var(--color-accent-green)]";
437	    if (grade.startsWith("B")) return "text-[var(--color-accent-blue)]";
438	    if (grade.startsWith("C")) return "text-[var(--color-accent-amber)]";
439	    return "text-[var(--color-accent-red)]";
440	  };
441	
442	  return (
443	    <div class="flex flex-col h-full bg-[var(--color-paper-2)]">
444	      <div class="px-5 py-4 border-b border-[var(--color-paper-3)] bg-[var(--color-paper-soft)]">
445	        <p class="dept-label">Dept. of Rigor</p>
446	        <h2
447	          class="mt-0.5 text-xl text-[var(--color-ink)]"
448	          style="font-family: var(--font-display); font-weight: 600;"
449	        >
450	          The Galley Proof
451	        </h2>
452	        <p
453	          class="mt-2 text-xs leading-5 text-[var(--color-ink-light)]"
454	          style="font-family: var(--font-serif); font-style: italic;"
455	        >
456	          {summarizeBrief(brief)}
457	        </p>
458	      </div>
459	
460	      {!store.result && !store.isAnalyzing && (
461	        <div class="flex-1 flex flex-col items-center justify-center px-6 py-10 text-center">
462	          <p
463	            class="text-4xl"
464	            style="font-family: var(--font-display); color: var(--color-cobalt);"
465	          >
466	            ❧
467	          </p>
468	          <p
469	            class="mt-3 text-sm text-[var(--color-ink-light)] max-w-xs leading-6"
470	            style="font-family: var(--font-serif); font-style: italic;"
471	          >
472	            Send the galley to the proof desk. Five judges read it, then the
473	            rubric counts features the eye can't see.
474	          </p>
475	          <button onClick$={analyze} class="btn-press mt-5">
476	            Send to copyedit
477	          </button>
478	          {store.error && (
479	            <div class="mt-3 max-w-sm">
480	              <ApplicationNotice
481	                error={store.error}
482	                compact
483	                onRetry$={store.error.recovery.canRetry ? analyze : undefined}
484	                recoveryLabel="Open AI settings"
485	                recoveryHref="/settings/"
486	              />
487	            </div>
488	          )}
489	        </div>
490	      )}
491	
492	      {store.isAnalyzing && (
493	        <div
494	          class="flex-1 flex flex-col items-center justify-center px-6 py-10 text-center"
495	          role="status"
496	        >
497	          <div
498	            class="text-4xl animate-spin"
499	            aria-hidden="true"
500	            style="font-family: var(--font-display); color: var(--color-cobalt);"
501	          >
502	            ✦
503	          </div>
504	          <p
505	            class="mt-4 text-sm text-[var(--color-ink-muted)]"
506	            style="font-family: var(--font-typewriter); letter-spacing: 0.15em; text-transform: uppercase;"
507	          >
508	            Five judges reading…
509	          </p>
510	          <p
511	            class="mt-2 text-[11px] text-[var(--color-ink-muted)]"
512	            style="font-family: var(--font-typewriter); letter-spacing: 0.15em;"
513	          >
514	            Measuring sentence cadence, citation density, paragraph shape
515	          </p>
516	        </div>
517	      )}
518	
519	      {store.result && !store.isAnalyzing && (
520	        <div class="flex-1 overflow-y-auto">
521	          {/* Overall score */}
522	          <div class="px-5 py-5 border-b border-[var(--color-paper-3)] bg-[var(--color-paper-soft)]">
523	            <div class="flex items-stretch gap-4">
524	              <div
525	                class={`flex-shrink-0 w-20 h-20 flex items-center justify-center ${getGradeColor(store.result.overallGrade)}`}
526	                role="img"
527	                aria-label={`Overall grade ${store.result.overallGrade}, ${store.result.overallScore} of 100`}
528	                style={{
529	                  borderRadius: "999px",
530	                  border: "2.5px solid currentColor",
531	                  fontFamily: "var(--font-display)",
532	                  fontWeight: 700,
533	                  fontSize: "2.25rem",
534	                  lineHeight: 1,
535	                  fontStyle: "italic",
536	                  transform: "rotate(-4deg)",
537	                  background: "rgba(255,255,255,0.4)",
538	                }}
539	              >
540	                {store.result.overallGrade}
541	              </div>
542	              <div class="flex-1 min-w-0">
543	                <p class="dept-label">Editor's Mark</p>
544	                <p
545	                  class="mt-0.5 text-lg text-[var(--color-ink)]"
546	                  style="font-family: var(--font-display); font-weight: 600;"
547	                >
548	                  {store.result.overallScore}
549	                  <span class="text-sm text-[var(--color-ink-muted)]">
550	                    {" "}
551	                    / 100
552	                  </span>
553	                </p>
554	                <p
555	                  class="mt-1.5 text-xs leading-5 text-[var(--color-ink-light)]"
556	                  style="font-family: var(--font-serif); font-style: italic;"
557	                >
558	                  {store.result.summary}
559	                </p>
560	              </div>
561	            </div>
562	
563	            {/* Per-judge scorecard */}
564	            <div class="mt-4 pt-4 border-t border-dashed border-[var(--color-paper-3)]">
565	              <p class="dept-label">The Judges' Verdict</p>
566	              {store.error && (
567	                <div class="mt-2">
568	                  <ApplicationNotice
569	                    error={store.error}
570	                    compact
571	                    onRetry$={
572	                      store.error.recovery.canRetry ? analyze : undefined
573	                    }
574	                    recoveryLabel="Open AI settings"
575	                    recoveryHref="/settings/"
576	                  />
577	                </div>
578	              )}
579	              <ul class="mt-2 space-y-1.5">
580	                {store.result.judges.map((j) => (
581	                  <li
582	                    key={j.personaId}
583	                    class="flex items-start gap-2 text-[12px] leading-5"
584	                  >
585	                    <span
586	                      class="font-mono flex-shrink-0 w-6 text-right"
587	                      style={{
588	                        color:
589	                          j.score >= 7
590	                            ? "var(--color-accent-green)"
591	                            : j.score >= 4
592	                              ? "var(--color-accent-amber)"
593	                              : "var(--color-accent-red)",
594	                        fontWeight: 600,
595	                      }}
596	                    >
597	                      {j.score}
598	                    </span>
599	                    <span
600	                      class="flex-1 text-[var(--color-ink-light)]"
601	                      style="font-family: var(--font-serif); font-style: italic;"
602	                    >
603	                      <span class="not-italic font-semibold text-[var(--color-ink)]">
604	                        {j.personaId}
605	                      </span>
606	                      {" — "}
607	                      {j.rationale}
608	                    </span>
609	                  </li>
610	                ))}
611	              </ul>
612	            </div>
613	          </div>
614	
615	          {/* Criteria */}
616	          <div class="px-4 py-4 space-y-3">
617	            {store.result.criteria.map((criterion, idx) => (
618	              <RubricCriterionCard
619	                key={criterion.id}
620	                criterion={criterion}
621	                index={idx + 1}
622	                scoreColor={getScoreColor(criterion.score, criterion.maxScore)}
623	              />
624	            ))}
625	          </div>
626	
627	          {/* Full narrative review */}
628	          <div class="px-4 py-4 border-t border-dashed border-[var(--color-paper-3)]">
629	            <p class="dept-label">The Critic's Full Review</p>
630	            {store.result.review ? (
631	              <div
632	                class="comment-markdown mt-2 text-[13px] leading-6 text-[var(--color-ink)]"
633	                style="font-family: var(--font-serif);"
634	                dangerouslySetInnerHTML={renderMarkdown(store.result.review)}
635	              />
636	            ) : (
637	              <button
638	                onClick$={generateReview}
639	                disabled={store.isReviewing}
640	                class="btn-paper w-full mt-2"
641	              >
642	                {store.isReviewing
643	                  ? "✍ Writing the full review…"
644	                  : "✍ Expand to a full-page review"}
645	              </button>
646	            )}
647	          </div>
648	
649	          <div class="px-4 py-3 border-t border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] space-y-2">
650	            <Link
651	              href="/rubric"
652	              class="block w-full text-center text-xs text-[var(--color-ink-muted)] hover:text-[var(--color-accent)]"
653	              style="font-family: var(--font-typewriter); letter-spacing: 0.12em; text-transform: uppercase;"
654	            >
655	              Expand ↗ Full galley report
656	            </Link>
657	            <button onClick$={analyze} class="btn-paper w-full">
658	              ↻ Send back for re-reading
659	            </button>
660	          </div>
661	        </div>
662	      )}
663	    </div>
664	  );
665	});
666	
667	function RubricCriterionCard({
668	  criterion,
669	  scoreColor,
670	  index,
671	}: {
672	  criterion: RubricCriterion;
673	  scoreColor: string;
674	  index: number;
675	}) {
676	  const pct = Math.round((criterion.score / criterion.maxScore) * 100);
677	  const roman =
678	    ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X"][index - 1] ||
679	    `${index}`;
680	
681	  return (
682	    <div
683	      class="bg-[var(--color-paper)] border border-[var(--color-paper-3)] p-4"
684	      style="border-radius: 2px;"
685	    >
686	      <div class="flex items-baseline justify-between gap-3 mb-2">
687	        <div class="flex items-baseline gap-2 min-w-0">
688	          <span
689	            class="text-xs flex-shrink-0"
690	            style={{
691	              fontFamily: "var(--font-typewriter)",
692	              color: "var(--color-ink-muted)",
693	              letterSpacing: "0.15em",
694	            }}
695	          >
696	            §{roman}
697	          </span>
698	          <span
699	            class="text-sm text-[var(--color-ink)] truncate"
700	            style="font-family: var(--font-display); font-weight: 600;"
701	          >
702	            {criterion.label}
703	          </span>
704	        </div>
705	        <span
706	          class="text-xs flex-shrink-0"
707	          style={{
708	            color: scoreColor,
709	            fontFamily: "var(--font-typewriter)",
710	            letterSpacing: "0.1em",
711	          }}
712	        >
713	          {criterion.score}/{criterion.maxScore}
714	        </span>
715	      </div>
716	      <div
717	        class="w-full h-[3px] bg-[var(--color-paper-2)] mb-2.5"
718	        role="meter"
719	        aria-label={criterion.label}
720	        aria-valuemin={0}
721	        aria-valuemax={criterion.maxScore}
722	        aria-valuenow={criterion.score}
723	      >
724	        <div
725	          class="rubric-bar h-full"
726	          style={{
727	            width: `${pct}%`,
728	            backgroundColor: scoreColor,
729	          }}
730	        />
731	      </div>
732	      <p
733	        class="text-xs leading-5 text-[var(--color-ink-light)]"
734	        style="font-family: var(--font-serif);"
735	      >
736	        {criterion.feedback}
737	      </p>
738	      {pct < 60 && (
739	        <p
740	          class="mt-1.5 text-[11px] leading-5"
741	          style={{
742	            fontFamily: "var(--font-typewriter)",
743	            color: "var(--color-vermilion)",
744	          }}
745	        >
746	          Next move → {nextMoveFor(criterion.id)}
747	        </p>
748	      )}
749	    </div>
750	  );
751	}
752	
753	/** A concrete, prescriptive next step for a low-scoring criterion. */
754	function nextMoveFor(id: string): string {
755	  const moves: Record<string, string> = {
756	    thesis:
757	      "State the load-bearing claim in one sentence near the top, then make every section earn it.",
758	    evidence:
759	      "Pick the two weakest claims and attach a source, example, or number to each.",
760	    integrity:
761	      "Replace universal claims with testable claims; cut filler and add proof where the sentence asks for trust.",
762	    structure:
763	      "Add a section break or transition where the argument changes gears; cut a paragraph that repeats.",
764	    pacing:
765	      "Vary sentence length — break one long sentence in three, and merge two short ones.",
766	    voice:
767	      "Rewrite the opening line in the target tone; let it set the register for the rest.",
768	    vocabulary:
769	      "Replace three abstractions with concrete nouns; cut one piece of jargon per paragraph.",
770	    paragraph: "Split any paragraph over ~6 sentences; give each a single job.",
771	    engagement:
772	      "Put a stake or a question in the first 100 words so the reader knows why to continue.",
773	  };
774	  return (
775	    moves[id] ??
776	    "Make the one change that would most move this score, then re-read."
777	  );
778	}
779	
780	/* ── Helpers ───────────────────────────────────────────────────── */
781	
782	import { PERSONAS as DEFAULT_PERSONAS } from "../../utils/personas";
783	
784	function defaultPersonas() {
785	  return DEFAULT_PERSONAS;
786	}
787	
788	function buildCriteria(
789	  staticScore: StaticScore,
790	  judges: JudgeResult[],
791	  final: number,
792	  brief: ProjectBrief | null,
793	  sufficiency: { score: number; rationale: string },
794	  evidence: { score: number; rationale: string },
795	  integrity: { score: number; rationale: string },
796	): RubricCriterion[] {
797	  const audience = brief?.answers.audience || "the intended reader";
798	  const goal = brief?.answers.goal || "the central goal";
799	  const tone = brief?.answers.tone || "the target tone";
800	  const judgeMean =
801	    judges.length > 0
802	      ? Math.round(
803	          (judges.reduce((s, j) => s + j.score, 0) / judges.length) * 10,
804	        ) / 10
805	      : 0;
806	  return [
807	    {
808	      id: "thesis",
809	      label: "Thesis & Argument",
810	      description: "Clarity and strength of the central argument",
811	      score: Math.min(10, Math.round(judgeMean * 10) / 10),
812	      maxScore: 10,
813	      feedback: `Judges averaged ${judgeMean}/10 on the central claim. The next pass is to make the load-bearing claim visible earlier against the stated goal: ${goal}.`,
814	    },
815	    {
816	      id: "evidence",
817	      label: "Evidence & Support",
818	      description: "Quality and relevance of supporting evidence",
819	      score: Math.min(10, evidence.score),
820	      maxScore: 10,
821	      feedback: evidence.rationale,
822	    },
823	    {
824	      id: "sufficiency",
825	      label: "Sufficiency & Development",
826	      description:
827	        "Whether the draft develops enough on-topic material to earn its thesis or goal",
828	      score: sufficiency.score,
829	      maxScore: 10,
830	      feedback: sufficiency.rationale,
831	    },
832	    {
833	      id: "integrity",
834	      label: "Bullshit Resistance",
835	      description: "Unsupported certainty, filler, vagueness, and repetition",
836	      score: Math.min(10, integrity.score),
837	      maxScore: 10,
838	      feedback: integrity.rationale,
839	    },
840	    {
841	      id: "structure",
842	      label: "Organization & Flow",
843	      description: "Logical structure and transitions",
844	      score: Math.min(10, staticScore.perFeature.structure),
845	      maxScore: 10,
846	      feedback: `${staticScore.features.paragraphCount} paragraph${
847	        staticScore.features.paragraphCount === 1 ? "" : "s"
848	      } across ${staticScore.features.sentenceCount} sentences. ${staticScore.feedback[0] ?? ""}`,
849	    },
850	    {
851	      id: "pacing",
852	      label: "Pacing & Rhythm",
853	      description: "Sentence length variation and cadence",
854	      score: Math.min(10, staticScore.perFeature.pacing),
855	      maxScore: 10,
856	      feedback: `Average sentence is ${staticScore.features.avgSentenceLength.toFixed(
857	        1,
858	      )} words, with a standard deviation of ${staticScore.features.sentenceLengthStdDev.toFixed(
859	        1,
860	      )}. A healthy mix lives in 12-22 word sentences with variance of 5-10.`,
861	    },
862	    {
863	      id: "voice",
864	      label: "Voice & Tone",
865	      description: "Consistency of voice for the named audience",
866	      score: Math.min(10, judgeMean),
867	      maxScore: 10,
868	      feedback: `Target tone: ${tone}. Read aloud — does the cadence match the reader, ${audience}?`,
869	    },
870	    {
871	      id: "vocabulary",
872	      label: "Vocabulary & Diction",
873	      description: "Type-token ratio and word choice",
874	      score: Math.min(10, staticScore.perFeature.vocabulary),
875	      maxScore: 10,
876	      feedback: `Type-token ratio: ${(staticScore.features.uniqueWordsRatio * 100).toFixed(1)}% (${staticScore.features.avgWordLength.toFixed(1)} average word length). Healthy range: 35-60%.`,
877	    },
878	    {
879	      id: "paragraph",
880	      label: "Paragraph Shape",
881	      description: "Balance of short and long paragraphs",
882	      score: Math.min(10, staticScore.perFeature.paragraphShape),
883	      maxScore: 10,
884	      feedback: `${(staticScore.features.shortParagraphRatio * 100).toFixed(0)}% of paragraphs are short, ${(staticScore.features.longParagraphRatio * 100).toFixed(0)}% are long. A balance of 2-3 sentence paragraphs and 5-8 sentence paragraphs reads best.`,
885	    },
886	    {
887	      id: "engagement",
888	      label: "Reader Engagement",
889	      description: "Whether the reader reaches the success signal",
890	      score: Math.min(10, Math.max(0, Math.round((final / 100) * 10))),
891	      maxScore: 10,
892	      feedback: `Combined score ${final}/100. ${final >= 80 ? "Strong work — keep going." : final >= 65 ? "Real progress, but the room is still asking for more." : "The next pass is the important one."}`,
893	    },
894	  ];
895	}
