1	import {
2	  component$,
3	  useStore,
4	  useSignal,
5	  $,
6	  type PropFunction,
7	  useVisibleTask$,
8	} from "@builder.io/qwik";
9	import {
10	  type InterviewMessage,
11	  type InterviewTurnResult,
12	  type InterviewConfidence,
13	  type InterviewDossierDraft,
14	  hasConfiguredAiProvider,
15	  runClientInterviewTurn,
16	} from "../../utils/ai-client";
17	import { loadAiSettingsFromIdb } from "../../utils/idb";
18	import type {
19	  DossierAttachment,
20	  ProjectBrief,
21	  ProjectInterviewAnswers,
22	} from "../../types";
23	import { useConvexClient } from "../../utils/convex-context";
24	import { api } from "../../../convex/_generated/api";
25	import { DossierAttachmentsEditor } from "./dossier-attachments-editor";
26	import { ApplicationNotice } from "../ui/application-notice";
27	import type { AppError } from "../../types/application-errors";
28	import {
29	  createAppError,
30	  normalizeApplicationError,
31	} from "../../utils/application-errors";
32	
33	/**
34	 * The conversational interview. A chat-style replacement for the
35	 * form: the AI asks one question at a time, the writer answers in
36	 * free text, the AI asks the next question, and when it has enough
37	 * the AI synthesises a dossier the writer can review and accept.
38	 *
39	 * Two modes:
40	 *   - "first-run" — no prior brief. The conversation starts from
41	 *     scratch.
42	 *   - "refine"    — the writer has a dossier already; the AI
43	 *     cross-references it during the conversation.
44	 *
45	 * Non-streaming. Streaming the AI's question into the chat is a
46	 * polish pass for later — the current implementation waits for the
47	 * full response before showing the next message.
48	 */
49	
50	const FIELD_LABELS: Record<keyof ProjectInterviewAnswers, string> = {
51	  workingTitle: "Working title",
52	  format: "Format",
53	  audience: "Audience",
54	  goal: "Goal",
55	  tone: "Tone",
56	  constraints: "Constraints",
57	  successSignal: "Success signal",
58	};
59	
60	const FIELD_ORDER: Array<keyof ProjectInterviewAnswers> = [
61	  "workingTitle",
62	  "format",
63	  "audience",
64	  "goal",
65	  "tone",
66	  "constraints",
67	  "successSignal",
68	];
69	
70	const OPENING_QUESTION =
71	  "Tell me the piece in one sentence — the way you'd describe it to a friend at lunch.";
72	
73	const REFINE_OPENING_QUESTION =
74	  "Reading your current brief back to you, what feels off, or what has the draft outgrown?";
75	
76	interface ConversationalInterviewProps {
77	  mode: "first-run" | "refine";
78	  initialBrief?: ProjectBrief;
79	  initialAttachments?: DossierAttachment[];
80	  onComplete$: PropFunction<
81	    (payload: {
82	      answers: ProjectInterviewAnswers;
83	      attachments: DossierAttachment[];
84	    }) => void
85	  >;
86	  onCancel$?: PropFunction<() => void>;
87	  cancelLabel?: string;
88	  onUseForm$?: PropFunction<
89	    (payload: {
90	      answers: Partial<ProjectInterviewAnswers>;
91	      attachments: DossierAttachment[];
92	    }) => void
93	  >;
94	}
95	
96	interface Synthesis {
97	  brief: ProjectInterviewAnswers;
98	  confidence: Partial<
99	    Record<keyof ProjectInterviewAnswers, InterviewConfidence>
100	  >;
101	}
102	
103	interface ComponentStore {
104	  messages: InterviewMessage[];
105	  loading: boolean;
106	  error: AppError | null;
107	  pendingWriterText: string | null;
108	  synthesis: Synthesis | null;
109	  liveDraft: InterviewDossierDraft | null;
110	  /** When the writer edits a field of the synthesis before accepting. */
111	  editingField: keyof ProjectInterviewAnswers | null;
112	  draft: string;
113	  initialized: boolean;
114	  attachments: DossierAttachment[];
115	  requestVersion: number;
116	}
117	
118	function confidenceTone(c: InterviewConfidence | undefined): string {
119	  if (c === "high") return "bg-[var(--color-accent-green)]";
120	  if (c === "low") return "bg-[var(--color-vermilion)]";
121	  return "bg-[var(--color-mustard)]";
122	}
123	
124	function confidenceLabel(c: InterviewConfidence | undefined): string {
125	  if (c === "high") return "high confidence";
126	  if (c === "low") return "low confidence";
127	  return "inferred";
128	}
129	
130	function mergeDossierDraft(
131	  current: InterviewDossierDraft | null,
132	  next: InterviewDossierDraft | undefined,
133	): InterviewDossierDraft | null {
134	  if (!next) return current;
135	  return {
136	    brief: { ...(current?.brief ?? {}), ...next.brief },
137	    confidence: { ...(current?.confidence ?? {}), ...next.confidence },
138	  };
139	}
140	
141	export const ConversationalInterview = component$(
142	  (props: ConversationalInterviewProps) => {
143	    const store = useStore<ComponentStore>({
144	      messages: [],
145	      loading: false,
146	      error: null,
147	      pendingWriterText: null,
148	      synthesis: null,
149	      liveDraft: props.initialBrief
150	        ? { brief: props.initialBrief.answers, confidence: {} }
151	        : null,
152	      editingField: null,
153	      draft: "",
154	      initialized: false,
155	      attachments: props.initialAttachments ?? [],
156	      requestVersion: 0,
157	    });
158	    const inputRef = useSignal<HTMLTextAreaElement>();
159	    const scrollerRef = useSignal<HTMLDivElement>();
160	    const clientSig = useConvexClient();
161	
162	    /**
163	     * Kick the conversation off with the AI's opening question.
164	     * The AI may answer with a question (normal) or with a synthesis
165	     * (rare — the writer has nothing yet, so this would only happen
166	     * if the writer said "synthesize" with no prior turns; we handle
167	     * it anyway).
168	     */
169	    // eslint-disable-next-line qwik/no-use-visible-task
170	    useVisibleTask$(async () => {
171	      if (store.initialized) return;
172	      store.initialized = true;
173	
174	      const opening =
175	        props.mode === "refine" ? REFINE_OPENING_QUESTION : OPENING_QUESTION;
176	
177	      // Seed the writer side with an empty reply slot for the AI
178	      // to fill. The interview always starts with the AI asking.
179	      store.messages = [{ author: "interviewer", text: opening }];
180	      // (The opening question is hard-coded — no AI call needed for
181	      // the first turn.)
182	    });
183	
184	    /**
185	     * Auto-scroll the message thread to the bottom when a new
186	     * message lands. Cheap because the thread is bounded.
187	     */
188	    // eslint-disable-next-line qwik/no-use-visible-task
189	    useVisibleTask$(({ track }) => {
190	      track(() => store.messages.length);
191	      track(() => store.synthesis);
192	      const el = scrollerRef.value;
193	      if (el) el.scrollTop = el.scrollHeight;
194	    });
195	
196	    const runTurn = $(async (writerText: string, appendWriter = true) => {
197	      const requestVersion = ++store.requestVersion;
198	      if (appendWriter) {
199	        store.messages = [
200	          ...store.messages,
201	          { author: "writer", text: writerText },
202	        ];
203	      }
204	      store.pendingWriterText = writerText;
205	      store.loading = true;
206	      store.error = null;
207	
208	      try {
209	        const settings = await loadAiSettingsFromIdb();
210	        let result: InterviewTurnResult | null = null;
211	        const hasByok = hasConfiguredAiProvider(settings);
212	
213	        if (hasByok && settings) {
214	          const clientResult = await runClientInterviewTurn(
215	            {
216	              messages: store.messages,
217	              mode: props.mode,
218	              currentBrief: props.initialBrief ?? null,
219	            },
220	            settings,
221	          );
222	          if (!clientResult.ok) {
223	            store.error = clientResult.error;
224	            return;
225	          }
226	          result = clientResult.value;
227	        }
228	
229	        if (requestVersion !== store.requestVersion) return;
230	
231	        if (!result && !hasByok && clientSig.value) {
232	          try {
233	            result = (await clientSig.value.action(
234	              (api as any).agents.runInterviewTurn,
235	              {
236	                messages: store.messages,
237	                mode: props.mode,
238	                currentBrief: props.initialBrief ?? null,
239	              },
240	            )) as InterviewTurnResult | null;
241	          } catch (error) {
242	            store.error = normalizeApplicationError(error, {
243	              source: "convex",
244	              metadata: { feature: "interview-turn" },
245	            });
246	            return;
247	          }
248	        }
249	
250	        if (requestVersion !== store.requestVersion) return;
251	
252	        if (!result) {
253	          store.error = createAppError(
254	            clientSig.value ? "AUTHENTICATION_REQUIRED" : "CONFIGURATION_ERROR",
255	            {
256	              recovery: {
257	                action: clientSig.value ? "sign-in" : "choose-provider",
258	                canRetry: false,
259	              },
260	              metadata: { feature: "interview-turn" },
261	            },
262	          );
263	          return;
264	        }
265	
266	        if (result.kind === "question") {
267	          store.liveDraft = mergeDossierDraft(store.liveDraft, result.draft);
268	          store.messages = [
269	            ...store.messages,
270	            { author: "interviewer", text: result.text },
271	          ];
272	        } else {
273	          // Synthesis — fill any missing field with the writer's
274	          // own current answer so the dossier is never empty.
275	          const current = props.initialBrief?.answers;
276	          const brief: ProjectInterviewAnswers = {
277	            workingTitle:
278	              result.brief.workingTitle || current?.workingTitle || "",
279	            format: result.brief.format || current?.format || "",
280	            audience: result.brief.audience || current?.audience || "",
281	            goal: result.brief.goal || current?.goal || "",
282	            tone: result.brief.tone || current?.tone || "",
283	            constraints: result.brief.constraints || current?.constraints || "",
284	            successSignal:
285	              result.brief.successSignal || current?.successSignal || "",
286	          };
287	          store.synthesis = { brief, confidence: result.confidence };
288	          store.liveDraft = { brief, confidence: result.confidence };
289	        }
290	        store.pendingWriterText = null;
291	      } catch (error) {
292	        store.error = normalizeApplicationError(error, {
293	          metadata: { feature: "interview-turn" },
294	        });
295	      } finally {
296	        if (requestVersion === store.requestVersion) {
297	          store.loading = false;
298	        }
299	      }
300	    });
301	
302	    const send = $(async () => {
303	      if (store.loading || store.synthesis) return;
304	      const text = store.draft.trim();
305	      if (!text) return;
306	      await runTurn(text);
307	      if (!store.error) store.draft = "";
308	    });
309	
310	    const retryTurn = $(async () => {
311	      const pending = store.pendingWriterText;
312	      if (!pending || store.loading) return;
313	      await runTurn(pending, false);
314	    });
315	
316	    const useForm = $(() => {
317	      store.requestVersion += 1;
318	      props.onUseForm$?.({
319	        answers:
320	          store.synthesis?.brief ??
321	          store.liveDraft?.brief ??
322	          props.initialBrief?.answers ??
323	          {},
324	        attachments: store.attachments,
325	      });
326	    });
327	
328	    const cancelOrUseForm = $(() => {
329	      store.requestVersion += 1;
330	      if (props.onUseForm$) {
331	        props.onUseForm$({
332	          answers:
333	            store.synthesis?.brief ??
334	            store.liveDraft?.brief ??
335	            props.initialBrief?.answers ??
336	            {},
337	          attachments: store.attachments,
338	        });
339	        return;
340	      }
341	      props.onCancel$?.();
342	    });
343	
344	    const dismissError = $(() => {
345	      store.error = null;
346	    });
347	
348	    const requestSynthesis = $(async () => {
349	      if (store.loading) return;
350	      // The writer can ask for the dossier at any point. We just
351	      // send an empty-ish nudge so the model knows to synthesise
352	      // rather than ask another question.
353	      await runTurn(
354	        "(the writer is ready to see the dossier — please synthesise now)",
355	        false,
356	      );
357	    });
358	
359	    const acceptSynthesis = $(() => {
360	      if (!store.synthesis) return;
361	      void props.onComplete$({
362	        answers: store.synthesis.brief,
363	        attachments: store.attachments,
364	      });
365	    });
366	
367	    const applyEdit = $((field: keyof ProjectInterviewAnswers) => {
368	      if (!store.synthesis || !store.editingField) return;
369	      const value = store.draft.trim();
370	      if (!value) return;
371	      store.synthesis = {
372	        ...store.synthesis,
373	        brief: { ...store.synthesis.brief, [field]: value },
374	        confidence: { ...store.synthesis.confidence, [field]: "high" },
375	      };
376	      store.draft = "";
377	      store.editingField = null;
378	    });
379	
380	    const startEditing = $((field: keyof ProjectInterviewAnswers) => {
381	      if (!store.synthesis) return;
382	      store.editingField = field;
383	      store.draft = store.synthesis.brief[field] ?? "";
384	      // Focus the input next tick
385	      setTimeout(() => inputRef.value?.focus(), 0);
386	    });
387	
388	    const dismissSynthesis = $(() => {
389	      // The writer wants to keep talking. Drop the synthesis and
390	      // resume the conversation.
391	      store.synthesis = null;
392	      store.editingField = null;
393	      store.draft = "";
394	    });
395	
396	    const livePanel = store.synthesis
397	      ? { brief: store.synthesis.brief, confidence: store.synthesis.confidence }
398	      : store.liveDraft;
399	
400	    return (
401	      <div
402	        class="min-h-screen flex flex-col bg-[var(--color-paper)] text-[var(--color-ink)]"
403	        style={{ fontFamily: "var(--font-serif)" }}
404	      >
405	        {/* Header */}
406	        <header class="px-6 py-4 border-b border-[var(--color-paper-3)] bg-[var(--color-paper-2)]/90 backdrop-blur-sm flex items-center justify-between">
407	          <div>
408	            <p
409	              class="text-[0.6rem] tracking-[0.32em] uppercase text-[var(--color-ink-muted)]"
410	              style={{ fontFamily: "var(--font-typewriter)" }}
411	            >
412	              {props.mode === "refine" ? "Refine the dossier" : "The interview"}
413	            </p>
414	            <h1
415	              class="text-lg leading-tight mt-0.5"
416	              style={{ fontFamily: "var(--font-display)", fontWeight: 600 }}
417	            >
418	              {props.mode === "refine"
419	                ? "The room reads your draft."
420	                : "Begin with a one-liner."}
421	            </h1>
422	          </div>
423	          {props.onCancel$ && (
424	            <button
425	              onClick$={cancelOrUseForm}
426	              class="text-[var(--color-ink-muted)] hover:text-[var(--color-ink)] text-sm"
427	              style={{
428	                fontFamily: "var(--font-typewriter)",
429	                letterSpacing: "0.1em",
430	              }}
431	            >
432	              {props.cancelLabel ?? "Cancel"}
433	            </button>
434	          )}
435	        </header>
436	
437	        {/* Thread */}
438	        <div
439	          ref={scrollerRef}
440	          class="flex-1 overflow-y-auto px-4 py-6 space-y-4"
441	        >
442	          <div class="mx-auto grid max-w-6xl gap-5 lg:grid-cols-[minmax(0,1fr)_22rem]">
443	            <div class="space-y-4">
444	              {store.messages.map((m, i) => (
445	                <div
446	                  key={i}
447	                  class={`flex ${m.author === "writer" ? "justify-end" : "justify-start"}`}
448	                >
449	                  <div
450	                    class={`max-w-[80%] rounded-[3px] px-4 py-2.5 leading-relaxed text-[0.95rem] ${
451	                      m.author === "writer"
452	                        ? "bg-[var(--color-vermilion)] text-white"
453	                        : "bg-[var(--color-paper-2)] border border-[var(--color-paper-3)] text-[var(--color-ink)]"
454	                    }`}
455	                    style={{
456	                      fontFamily:
457	                        m.author === "writer"
458	                          ? "var(--font-serif)"
459	                          : "var(--font-display)",
460	                    }}
461	                  >
462	                    {m.author === "interviewer" && (
463	                      <p
464	                        class="text-[0.55rem] tracking-[0.24em] uppercase mb-1 text-[var(--color-ink-muted)]"
465	                        style={{ fontFamily: "var(--font-typewriter)" }}
466	                      >
467	                        The room
468	                      </p>
469	                    )}
470	                    {m.text}
471	                  </div>
472	                </div>
473	              ))}
474	
475	              {store.loading && (
476	                <div class="flex justify-start">
477	                  <div class="bg-[var(--color-paper-2)] border border-[var(--color-paper-3)] rounded-[3px] px-4 py-2.5">
478	                    <span
479	                      class="text-[var(--color-ink-muted)] text-sm"
480	                      style={{ fontFamily: "var(--font-typewriter)" }}
481	                    >
482	                      The room is reading…
483	                    </span>
484	                  </div>
485	                </div>
486	              )}
487	
488	              {store.synthesis && (
489	                <div class="bg-[var(--color-paper-2)] border border-[var(--color-paper-3)] rounded-[2px] p-5 shadow-sm space-y-4">
490	                  <div>
491	                    <p
492	                      class="text-[0.6rem] tracking-[0.24em] uppercase text-[var(--color-ink-muted)] mb-1"
493	                      style={{ fontFamily: "var(--font-typewriter)" }}
494	                    >
495	                      Draft dossier
496	                    </p>
497	                    <p
498	                      class="text-base"
499	                      style={{
500	                        fontFamily: "var(--font-display)",
501	                        fontWeight: 600,
502	                      }}
503	                    >
504	                      The room's first pass. Edit anything before you take it to
505	                      the desk.
506	                    </p>
507	                  </div>
508	
509	                  <dl class="space-y-3">
510	                    {FIELD_ORDER.map((field) => {
511	                      const value = store.synthesis!.brief[field];
512	                      const conf = store.synthesis!.confidence[field];
513	                      const isEditing = store.editingField === field;
514	                      return (
515	                        <div
516	                          key={field}
517	                          class="border-l-2 border-[var(--color-paper-3)] pl-3 py-1"
518	                        >
519	                          <dt
520	                            class="text-[0.6rem] tracking-[0.2em] uppercase text-[var(--color-ink-muted)] flex items-center gap-2 mb-1"
521	                            style={{ fontFamily: "var(--font-typewriter)" }}
522	                          >
523	                            <span
524	                              class={`inline-block w-1.5 h-1.5 rounded-full ${confidenceTone(conf)}`}
525	                              aria-hidden="true"
526	                            />
527	                            {FIELD_LABELS[field]}
528	                            <span
529	                              class="text-[0.55rem] tracking-[0.1em] normal-case text-[var(--color-ink-muted)]"
530	                              style={{ fontFamily: "var(--font-typewriter)" }}
531	                            >
532	                              ({confidenceLabel(conf)})
533	                            </span>
534	                          </dt>
535	                          <dd
536	                            class="text-[0.95rem] leading-relaxed"
537	                            style={{ fontFamily: "var(--font-serif)" }}
538	                          >
539	                            {isEditing ? (
540	                              <div class="space-y-2">
541	                                <textarea
542	                                  ref={inputRef}
543	                                  value={store.draft}
544	                                  onInput$={(_, el) => {
545	                                    store.draft = el.value;
546	                                  }}
547	                                  rows={3}
548	                                  class="w-full border border-[var(--color-paper-3)] rounded px-2 py-1.5 text-sm bg-[var(--color-paper-soft)] focus:outline-none focus:border-[var(--color-vermilion)]"
549	                                  style={{ fontFamily: "var(--font-serif)" }}
550	                                />
551	                                <div class="flex items-center gap-2">
552	                                  <button
553	                                    onClick$={() => applyEdit(field)}
554	                                    class="text-xs px-3 py-1 rounded bg-[var(--color-vermilion)] text-white"
555	                                    style={{
556	                                      fontFamily: "var(--font-typewriter)",
557	                                    }}
558	                                  >
559	                                    Save
560	                                  </button>
561	                                  <button
562	                                    onClick$={() => {
563	                                      store.editingField = null;
564	                                      store.draft = "";
565	                                    }}
566	                                    class="text-xs text-[var(--color-ink-muted)] hover:text-[var(--color-ink)]"
567	                                    style={{
568	                                      fontFamily: "var(--font-typewriter)",
569	                                    }}
570	                                  >
571	                                    Cancel
572	                                  </button>
573	                                </div>
574	                              </div>
575	                            ) : (
576	                              <div class="flex items-start justify-between gap-2">
577	                                <span class="flex-1">
578	                                  {value || (
579	                                    <em class="text-[var(--color-ink-muted)] italic">
580	                                      (empty — the room wasn't sure)
581	                                    </em>
582	                                  )}
583	                                </span>
584	                                <button
585	                                  onClick$={() => startEditing(field)}
586	                                  class="text-[0.6rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-vermilion)] flex-shrink-0"
587	                                  style={{
588	                                    fontFamily: "var(--font-typewriter)",
589	                                  }}
590	                                >
591	                                  Edit
592	                                </button>
593	                              </div>
594	                            )}
595	                          </dd>
596	                        </div>
597	                      );
598	                    })}
599	                  </dl>
600	
601	                  <div class="border-t border-[var(--color-paper-3)] pt-4">
602	                    <p
603	                      class="text-[0.6rem] tracking-[0.24em] uppercase text-[var(--color-ink-muted)] mb-2"
604	                      style={{ fontFamily: "var(--font-typewriter)" }}
605	                    >
606	                      Reference material
607	                    </p>
608	                    <DossierAttachmentsEditor
609	                      attachments={store.attachments}
610	                      onChange$={(next) => {
611	                        store.attachments = next;
612	                      }}
613	                    />
614	                  </div>
615	
616	                  <div class="flex items-center gap-2 pt-2 border-t border-[var(--color-paper-3)]">
617	                    <button
618	                      onClick$={acceptSynthesis}
619	                      class="flex-1 rounded-full bg-[var(--color-vermilion)] text-white px-5 py-2.5 text-sm font-semibold hover:opacity-90 transition-opacity"
620	                      style={{ fontFamily: "var(--font-display)" }}
621	                    >
622	                      Take it to the desk
623	                    </button>
624	                    <button
625	                      onClick$={dismissSynthesis}
626	                      class="text-[var(--color-ink-muted)] hover:text-[var(--color-ink)] text-sm px-4 py-2.5"
627	                      style={{ fontFamily: "var(--font-typewriter)" }}
628	                    >
629	                      Keep talking
630	                    </button>
631	                  </div>
632	                </div>
633	              )}
634	            </div>
635	
636	            <aside class="lg:sticky lg:top-4 lg:self-start border border-[var(--color-paper-3)] bg-[var(--color-paper-2)] p-4 shadow-sm">
637	              <div class="flex items-center justify-between gap-3">
638	                <div>
639	                  <p
