641	                    style={{ fontFamily: "var(--font-typewriter)" }}
642	                  >
643	                    Room brief
644	                  </p>
645	                  <h2
646	                    class="mt-1 text-base"
647	                    style={{
648	                      fontFamily: "var(--font-display)",
649	                      fontWeight: 600,
650	                    }}
651	                  >
652	                    Filling as you talk
653	                  </h2>
654	                </div>
655	                <span
656	                  class={`block h-2 w-2 rounded-full ${
657	                    store.synthesis
658	                      ? "bg-[var(--color-accent-green)]"
659	                      : "bg-[var(--color-mustard)]"
660	                  }`}
661	                  aria-hidden="true"
662	                />
663	              </div>
664	
665	              <dl class="mt-4 space-y-3">
666	                {FIELD_ORDER.map((field) => {
667	                  const value = livePanel?.brief[field];
668	                  const conf = livePanel?.confidence[field];
669	                  return (
670	                    <div
671	                      key={field}
672	                      class="border-l-2 border-[var(--color-paper-3)] pl-3"
673	                    >
674	                      <dt
675	                        class="flex items-center gap-2 text-[0.57rem] tracking-[0.18em] uppercase text-[var(--color-ink-muted)]"
676	                        style={{ fontFamily: "var(--font-typewriter)" }}
677	                      >
678	                        <span
679	                          class={`inline-block h-1.5 w-1.5 rounded-full ${
680	                            value
681	                              ? confidenceTone(conf)
682	                              : "bg-[var(--color-paper-3)]"
683	                          }`}
684	                          aria-hidden="true"
685	                        />
686	                        {FIELD_LABELS[field]}
687	                      </dt>
688	                      <dd class="mt-1 text-sm leading-6 text-[var(--color-ink-light)]">
689	                        {value || (
690	                          <span class="italic text-[var(--color-ink-muted)]">
691	                            Waiting for evidence.
692	                          </span>
693	                        )}
694	                      </dd>
695	                    </div>
696	                  );
697	                })}
698	              </dl>
699	
700	              <p
701	                class="mt-4 border-t border-[var(--color-paper-3)] pt-3 text-[0.72rem] leading-5 text-[var(--color-ink-muted)]"
702	                style={{ fontFamily: "var(--font-typewriter)" }}
703	              >
704	                When the room has enough, it will ask you to review before
705	                opening the editor.
706	              </p>
707	            </aside>
708	          </div>
709	        </div>
710	
711	        {/* Composer */}
712	        {!store.synthesis && (
713	          <div class="border-t border-[var(--color-paper-3)] bg-[var(--color-paper-2)] px-4 py-3">
714	            <div class="max-w-2xl mx-auto">
715	              {store.error && (
716	                <div class="mb-3">
717	                  <ApplicationNotice
718	                    error={store.error}
719	                    busy={store.loading}
720	                    onRetry$={
721	                      store.error.recovery.canRetry ? retryTurn : undefined
722	                    }
723	                    recoveryLabel={
724	                      store.error.code === "AUTHENTICATION_REQUIRED"
725	                        ? "Sign in"
726	                        : props.onUseForm$
727	                          ? "Use the form"
728	                          : "Open AI settings"
729	                    }
730	                    recoveryHref={
731	                      store.error.code === "AUTHENTICATION_REQUIRED"
732	                        ? "/signin/"
733	                        : props.onUseForm$
734	                          ? undefined
735	                          : "/settings/"
736	                    }
737	                    onRecovery$={props.onUseForm$ ? useForm : undefined}
738	                    onDismiss$={dismissError}
739	                  />
740	                </div>
741	              )}
742	              <textarea
743	                value={store.draft}
744	                onInput$={(_, el) => {
745	                  store.draft = el.value;
746	                }}
747	                onKeyDown$={(e) => {
748	                  if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
749	                    void send();
750	                  }
751	                }}
752	                rows={3}
753	                placeholder={
754	                  store.messages.length <= 1
755	                    ? "Type your answer here. ⌘↩ to send."
756	                    : "Type your answer. ⌘↩ to send."
757	                }
758	                disabled={store.loading}
759	                class="w-full border border-[var(--color-paper-3)] rounded px-3 py-2 text-sm bg-[var(--color-paper-soft)] focus:outline-none focus:border-[var(--color-vermilion)] disabled:opacity-50"
760	                style={{ fontFamily: "var(--font-serif)" }}
761	              />
762	              <div class="flex items-center justify-between mt-2">
763	                <button
764	                  onClick$={requestSynthesis}
765	                  disabled={store.loading || store.messages.length < 3}
766	                  class="text-[0.65rem] tracking-[0.15em] uppercase text-[var(--color-ink-muted)] hover:text-[var(--color-ink)] disabled:opacity-30"
767	                  style={{ fontFamily: "var(--font-typewriter)" }}
768	                  title="Ask the room to synthesise the dossier now"
769	                >
770	                  → Show me what you have
771	                </button>
772	                <button
773	                  onClick$={send}
774	                  disabled={store.loading || !store.draft.trim()}
775	                  class="rounded-full bg-[var(--color-vermilion)] text-white px-4 py-1.5 text-sm disabled:opacity-30"
776	                  style={{ fontFamily: "var(--font-display)" }}
777	                >
778	                  Send
779	                </button>
780	              </div>
781	            </div>
782	          </div>
783	        )}
784	      </div>
785	    );
786	  },
787	);
