243	  const temperature = provider.label === "openai" ? 0.6 : 0.4;
244	  const start = Date.now();
245	  const { tools, getAnchor } = buildQuoteTools(req.draftText);
246	
247	  try {
248	    const { text } = await generateText({
249	      model: provider.model,
250	      system,
251	      prompt: user,
252	      temperature,
253	      maxOutputTokens: maxTokens,
254	      tools,
255	      stopWhen: stepCountIs(3),
256	      experimental_telemetry: {
257	        isEnabled: tracingEnabled,
258	        functionId: feature,
259	        metadata: {
260	          feature,
261	          persona: req.persona.id,
262	          provider: provider.label,
263	          model: provider.modelId,
264	        },
265	      },
266	    });
267	    let visibleText = stripReasoningTags(text);
268	    // Reasoning models can wrap the whole reply in <think>; regenerate once
269	    // so the note is never blank, then fall back to the raw text.
270	    if (!visibleText) {
