304	    const cleaned = visibleText.trim();
305	    await flushArize();
306	    return {
307	      text: cleaned || "(no response)",
308	      type: classifyType(cleaned, fallbackType),
309	      provider: provider.label,
310	      anchor: getAnchor() ?? req.anchor,
311	    };
312	  } catch (err) {
313	    await captureServerAiGeneration({
314	      feature,
315	      provider: provider.label,
316	      model: provider.modelId,
317	      req,
318	      latencyMs: Date.now() - start,
319	      temperature,
320	      maxTokens,
321	      spanName: feature,
322	      error: err,
323	    });
