463	const INTERVIEW_FIELDS = [
464	  "workingTitle",
465	  "format",
466	  "audience",
467	  "goal",
468	  "tone",
469	  "constraints",
470	  "successSignal",
471	] as const satisfies ReadonlyArray<keyof ProjectInterviewAnswers>;
