473	function interviewSystemPrompt(
474	  mode: "first-run" | "refine",
475	  currentBrief: ProjectBrief | null,
476	): string {
477	  return [
478	    "You are a kind, incisive editorial interviewer helping a writer build a project dossier.",
479	    "Ask one question at a time. Keep it short. You are building a writer's room: identify the piece, reader, goal, tone, constraints, success signal, and what kind of advisors/editors the writer wants around it.",
480	    'After every ordinary question, append `DOSSIER:` followed by JSON { "brief": { workingTitle, format, audience, goal, tone, constraints, successSignal }, "confidence": { field: "high" | "medium" | "low" } }. Only include fields you can reasonably infer.',
481	    "When the dossier is complete enough for review, respond only with `SYNTHESIZE:` followed by the same JSON shape. Put requested advisors/editors into constraints or goal until the product has a dedicated advisor schema.",
482	    mode === "refine" && currentBrief
483	      ? `Existing dossier: ${JSON.stringify(currentBrief.answers)} — refine it, don't restart.`
484	      : "",
485	  ]
486	    .filter(Boolean)
487	    .join("\n");
