490	function normalizeInterviewDossierDraft(value: unknown) {
491	  if (!value || typeof value !== "object") return null;
492	  const obj = value as Record<string, unknown>;
493	  const briefSource =
494	    obj.brief && typeof obj.brief === "object"
495	      ? (obj.brief as Record<string, unknown>)
496	      : obj;
497	  const confidenceSource =
498	    obj.confidence && typeof obj.confidence === "object"
499	      ? (obj.confidence as Record<string, unknown>)
500	      : {};
501	
502	  const brief: Partial<ProjectInterviewAnswers> = {};
503	  const confidence: Partial<
504	    Record<keyof ProjectInterviewAnswers, InterviewConfidence>
505	  > = {};
506	  for (const field of INTERVIEW_FIELDS) {
507	    const raw = briefSource[field];
508	    if (typeof raw === "string" && raw.trim()) {
509	      brief[field] = raw.trim();
510	    }
511	    const c = confidenceSource[field];
512	    if (c === "high" || c === "medium" || c === "low") {
513	      confidence[field] = c;
514	    }
515	  }
516	  return Object.keys(brief).length > 0 ? { brief, confidence } : null;
517	}
