519	function parseInterviewTurnResult(
520	  text: string,
521	  provider: string,
522	  model: string,
523	  messages: InterviewMessage[],
524	): InterviewTurnResult {
525	  const visibleText = stripReasoningTags(text);
526	  if (!visibleText.trim()) {
527	    throw applicationError("malformed_response");
528	  }
529	  const lastUser = [...messages].reverse().find((m) => m.author === "writer");
530	  const synthSegment = extractTaggedJson(visibleText, "SYNTHESIZE");
531	  if (synthSegment) {
532	    const draft = normalizeInterviewDossierDraft(synthSegment.value);
533	    if (draft) {
534	      return {
535	        kind: "synthesis",
536	        brief: draft.brief as ProjectInterviewAnswers,
537	        confidence: draft.confidence,
538	        provider,
539	        model,
540	      };
541	    }
542	    throw applicationError("malformed_response");
543	  }
544	
545	  const legacySynthMatch = visibleText.match(
546	    /SYNTHESIZE:\s*(\{[\s\S]*?\})\s*(\{[\s\S]*?\})?/,
547	  );
548	  if (legacySynthMatch) {
549	    try {
550	      return {
551	        kind: "synthesis",
552	        brief: JSON.parse(legacySynthMatch[1]) as ProjectInterviewAnswers,
553	        confidence: legacySynthMatch[2]
554	          ? (JSON.parse(legacySynthMatch[2]) as Partial<
555	              Record<keyof ProjectInterviewAnswers, InterviewConfidence>
556	            >)
557	          : {},
558	        provider,
559	        model,
560	      };
561	    } catch {
562	      throw applicationError("malformed_response");
563	    }
564	  }
565	
566	  const dossierSegment = extractTaggedJson(visibleText, "DOSSIER");
567	  if (!dossierSegment && /\b(?:DOSSIER|SYNTHESIZE)\s*:/i.test(visibleText)) {
568	    throw applicationError("malformed_response");
569	  }
570	  const draft = dossierSegment
571	    ? normalizeInterviewDossierDraft(dossierSegment.value)
572	    : null;
573	  const reply =
574	    (dossierSegment
575	      ? stripTaggedJson(visibleText, dossierSegment)
576	      : visibleText
577	    ).trim() ||
578	    (lastUser ? "Tell me more." : "What is the working title of this piece?");
579	
580	  return {
581	    kind: "question",
582	    text: reply,
583	    draft: draft ?? undefined,
584	    provider,
585	    model,
586	  };
587	}
