737	/** Parse the strict-JSON rewrite contract, tolerating code fences / prose. */
738	function parseRewriteOutput(
739	  text: string,
740	): { replacement: string; rationale: string } | null {
741	  const stripped = stripReasoningTags(text)
742	    .trim()
743	    .replace(/^```(?:json)?/i, "")
744	    .replace(/```$/, "")
745	    .trim();
746	  const tryParse = (s: string) => {
747	    try {
748	      const o = JSON.parse(s);
749	      if (o && typeof o.replacement === "string" && o.replacement.trim()) {
750	        return {
751	          replacement: o.replacement.trim(),
752	          rationale: typeof o.rationale === "string" ? o.rationale.trim() : "",
753	        };
754	      }
755	    } catch {
756	      /* fall through */
757	    }
758	    return null;
759	  };
760	  return (
761	    tryParse(stripped) ?? tryParse(stripped.match(/\{[\s\S]*\}/)?.[0] ?? "")
762	  );
763	}
