236	    editor: longest,
237	    devil: claim >= 0 ? claim : Math.floor(sentences.length / 2),
238	    scholar: evidence >= 0 ? evidence : Math.floor((sentences.length * 2) / 3),
239	    angel: Math.floor(sentences.length / 3),
240	  };
