  judges,
  staticScore,
  brief,
  targetFit.score,
);
const criteria = buildCriteria(
  staticScore,
  judges,
  combined.combined,
  brief,
  sufficiency,
  evidence,
  integrity,
  targetFit,
);

const result: RubricResult = {
  criteria,
  overallScore: combined.combined,
  overallGrade: combined.grade,
  summary: combined.summary,
  timestamp: Date.now(),
  judges,
  staticScore,
  targetFit: targetFit.score,
};

