  // The static score only earns its full weight when the content is actually
  // on-target. Off-target prose can still be beautifully shaped, and that
  // shapeliness must not be allowed to lift the grade — so the weight it
  // would have had is handed to the harshest judge instead, who is the one
  // reader most likely to have noticed the drift.
  const staticWeight = STATIC_WEIGHT * (fit / 10);
  const minJudgeWeight = MIN_JUDGE_WEIGHT + (STATIC_WEIGHT - staticWeight);

  // Combined score on a 0-10 scale, then mapped to 0-100 with a curve
  // designed to be brutal. Most drafts should land in the 40-65 range;
  // a 90+ is reserved for genuinely excellent work.
  const combinedTen =
    judgeMean * JUDGE_WEIGHT +
    minJudge * minJudgeWeight +
    staticTotal * staticWeight;
  const combinedHundred = brutalCurve(combinedTen * 10);
  const grade = letterGrade(combinedHundred);

  return {
    judgeMean,
    minJudge,
    staticTotal,
    combined: Math.round(combinedHundred),
    grade,
    summary: buildSummary(judges, staticScore, combinedHundred, brief, fit),
    targetFit: fit,
    staticWeight: Math.round(staticWeight * 1000) / 1000,
  };
}

