61	/* ── Database lifecycle ─────────────────────────────────────────── */
62	
63	let _dbPromise: Promise<IDBDatabase> | null = null;
64	
65	function openDb(): Promise<IDBDatabase> {
66	  if (typeof indexedDB === "undefined") {
67	    return Promise.reject(new Error("IndexedDB unavailable"));
68	  }
69	  if (_dbPromise) return _dbPromise;
70	
71	  _dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
72	    const req = indexedDB.open(DB_NAME, DB_VERSION);
73	    req.onupgradeneeded = () => {
74	      const db = req.result;
75	      if (!db.objectStoreNames.contains("folios")) {
76	        db.createObjectStore("folios", { keyPath: "id" });
77	      }
78	      if (!db.objectStoreNames.contains("folio-content")) {
79	        db.createObjectStore("folio-content", { keyPath: "folioId" });
80	      }
81	      if (!db.objectStoreNames.contains("brief")) {
82	        db.createObjectStore("brief", { keyPath: "folioId" });
83	      }
84	      if (!db.objectStoreNames.contains("comments")) {
85	        db.createObjectStore("comments", { keyPath: "id" });
86	      }
87	      if (!db.objectStoreNames.contains("personas")) {
88	        db.createObjectStore("personas", { keyPath: "id" });
89	      }
90	      if (!db.objectStoreNames.contains("meta")) {
91	        db.createObjectStore("meta", { keyPath: "key" });
92	      }
93	      if (!db.objectStoreNames.contains("ai-settings")) {
94	        db.createObjectStore("ai-settings", { keyPath: "key" });
95	      }
96	      if (!db.objectStoreNames.contains("lix-blob")) {
97	        db.createObjectStore("lix-blob", { keyPath: "key" });
98	      }
99	      // v2: recorded voice notes, kept as Blobs alongside the transcripts
100	      // that live on the comments they are attached to.
101	      if (!db.objectStoreNames.contains("voice-notes")) {
102	        db.createObjectStore("voice-notes", { keyPath: "id" });
103	      }
104	    };
105	    req.onsuccess = () => resolve(req.result);
106	    req.onerror = () => reject(req.error);
107	    req.onblocked = () => reject(new Error("IndexedDB open blocked"));
108	  });
109	
110	  // Reset the cached promise on failure so the next call can retry.
111	  _dbPromise.catch(() => {
112	    _dbPromise = null;
113	  });
114	
115	  return _dbPromise;
116	}
