1	/**
2	 * Voice notes — recording, storing the audio, and turning it into text.
3	 *
4	 * The audio is kept, not discarded after transcription. That is the difference
5	 * between a voice note and dictation: transcription is lossy about tone,
6	 * hesitation and emphasis, and a writer replaying their own half-formed thought
7	 * hears things the transcript does not carry. So the Blob lives in IndexedDB
8	 * beside the folios, and the transcript is the searchable surface over it.
9	 *
10	 * Transcription follows the same provider chain as everything else: the
11	 * writer's own key first, then the Pro-gated hosted endpoint.
12	 */
13	
14	import type { ConvexClient } from "convex/browser";
15	import { api } from "../../convex/_generated/api";
16	import { runClientVoiceTranscribe, hasConfiguredAiProvider } from "./ai-client";
17	import { getCachedAiSettings } from "./ai-orchestrator";
18	import { loadVoiceNoteBlob, saveVoiceNoteBlob } from "./idb";
19	import { createAppError, normalizeApplicationError } from "./application-errors";
20	import type { AppError } from "../types/application-errors";
21	
22	/** Recording stops itself here. Long enough for a real thought, short enough
23	 *  that a forgotten open mic can't fill the disk or the API bill. */
24	export const MAX_RECORDING_MS = 3 * 60_000;
25	
26	/** Preferred container. Falls back through what the browser actually supports. */
27	const CANDIDATE_MIME_TYPES = [
28	  "audio/webm;codecs=opus",
29	  "audio/webm",
30	  "audio/ogg;codecs=opus",
31	  "audio/mp4",
32	];
33	
34	export function pickRecordingMimeType(): string {
35	  if (typeof MediaRecorder === "undefined") return "audio/webm";
36	  for (const type of CANDIDATE_MIME_TYPES) {
37	    if (MediaRecorder.isTypeSupported(type)) return type;
38	  }
39	  return "";
40	}
41	
42	export function canRecord(): boolean {
43	  return (
44	    typeof navigator !== "undefined" &&
45	    !!navigator.mediaDevices?.getUserMedia &&
46	    typeof MediaRecorder !== "undefined"
47	  );
48	}
49	
50	export interface Recording {
51	  blob: Blob;
52	  durationMs: number;
53	  mimeType: string;
54	}
55	
56	export interface RecorderHandle {
57	  /** Resolve with the finished recording. */
58	  stop: () => Promise<Recording>;
59	  /** Abandon the recording and release the microphone. */
60	  cancel: () => void;
61	  /** Current input level, 0-1, for a live meter. */
62	  level: () => number;
63	}
64	
65	/**
66	 * Start recording. Rejects with a structured error when the microphone is
67	 * unavailable or permission is refused — the caller shows it, and must not
68	 * treat a refusal as a bug.
69	 */
70	export async function startRecording(): Promise<RecorderHandle> {
71	  if (!canRecord()) {
72	    throw createAppError("CONFIGURATION_ERROR", {
73	      source: "application",
74	      recovery: { action: "none", canRetry: false },
75	      metadata: {
76	        feature: "voice-notes",
77	        operation: "record",
78	        reason: "no-media-recorder",
79	      },
80	    });
81	  }
82	
83	  let stream: MediaStream;
84	  try {
85	    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
86	  } catch (err) {
87	    throw normalizeApplicationError(err, {
88	      source: "application",
89	      metadata: { feature: "voice-notes", operation: "microphone-permission" },
90	    });
91	  }
92	
93	  const mimeType = pickRecordingMimeType();
94	  const recorder = new MediaRecorder(
95	    stream,
96	    mimeType ? { mimeType } : undefined,
97	  );
98	  const chunks: Blob[] = [];
99	  recorder.ondataavailable = (e) => {
100	    if (e.data.size > 0) chunks.push(e.data);
101	  };
102	
103	  // A live level meter, so the writer can see the mic is actually hearing
104	  // them. Failing to build one is not a reason to fail the recording.
105	  let analyser: AnalyserNode | null = null;
106	  let audioContext: AudioContext | null = null;
107	  let levelData: Uint8Array | null = null;
108	  try {
109	    audioContext = new AudioContext();
110	    const source = audioContext.createMediaStreamSource(stream);
111	    analyser = audioContext.createAnalyser();
112	    analyser.fftSize = 256;
113	    source.connect(analyser);
114	    levelData = new Uint8Array(analyser.frequencyBinCount);
115	  } catch {
116	    analyser = null;
117	  }
118	
119	  const startedAt = Date.now();
120	  recorder.start();
121	
122	  const release = () => {
123	    for (const track of stream.getTracks()) track.stop();
124	    void audioContext?.close().catch(() => {});
125	  };
126	
127	  let autoStop: ReturnType<typeof setTimeout> | null = null;
128	
129	  const stop = () =>
130	    new Promise<Recording>((resolve) => {
131	      if (autoStop) clearTimeout(autoStop);
132	      const finish = () => {
133	        release();
134	        resolve({
135	          blob: new Blob(chunks, { type: mimeType || "audio/webm" }),
136	          durationMs: Date.now() - startedAt,
137	          mimeType: mimeType || "audio/webm",
138	        });
139	      };
140	      if (recorder.state === "inactive") {
141	        finish();
142	        return;
143	      }
144	      recorder.onstop = finish;
145	      recorder.stop();
146	    });
147	
148	  autoStop = setTimeout(() => void stop(), MAX_RECORDING_MS);
149	
150	  return {
151	    stop,
152	    cancel: () => {
153	      if (autoStop) clearTimeout(autoStop);
154	      if (recorder.state !== "inactive") {
155	        recorder.onstop = null;
156	        recorder.stop();
157	      }
158	      release();
159	    },
160	    level: () => {
161	      if (!analyser || !levelData) return 0;
162	      analyser.getByteFrequencyData(levelData);
163	      let sum = 0;
164	      for (const v of levelData) sum += v;
165	      return Math.min(1, sum / levelData.length / 128);
166	    },
167	  };
168	}
169	
170	/* ── Persistence ────────────────────────────────────────────────── */
171	
172	export async function storeVoiceNote(
173	  id: string,
174	  blob: Blob,
175	): Promise<void> {
176	  await saveVoiceNoteBlob(id, blob);
177	}
178	
179	export async function readVoiceNote(id: string): Promise<Blob | null> {
180	  return loadVoiceNoteBlob(id);
181	}
182	
183	/* ── Transcription ──────────────────────────────────────────────── */
184	
185	export interface TranscriptionOutcome {
186	  text: string;
187	  provider: string;
188	}
189	
190	async function blobToBase64(blob: Blob): Promise<string> {
191	  const buffer = await blob.arrayBuffer();
192	  const bytes = new Uint8Array(buffer);
193	  // Chunked so a three-minute recording doesn't blow the argument limit of
194	  // String.fromCharCode with a single spread.
195	  let binary = "";
196	  const CHUNK = 0x8000;
197	  for (let i = 0; i < bytes.length; i += CHUNK) {
198	    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
199	  }
200	  return btoa(binary);
201	}
202	
203	/**
204	 * Turn a recording into text. BYOK first, then the Pro-gated hosted endpoint.
205	 * Throws a structured {@link AppError} when neither is reachable, so the
206	 * caller can offer the right recovery instead of a generic failure.
207	 */
