const normalized = normalizeAiSettings(settings);
if (normalized.providers.length === 0) {
  return null;
}

const override: AiFeatureOverride | undefined =
  normalized.perFeature[feature];
const providerId =
  override?.providerId ??
  normalized.defaultProviderId ??
