const key = (await Bun.$`skate get fish_audio_api_key`.text()).trim();
const picks: Array<[string, string, string]> = [
  ["devil",   "91f2fedea8bc4465a6c668b2776be809", "Strike the qualifier. Either you can defend the claim or you cannot."],
  ["angel",   "23c1b755b9994a68a1d21d6a67562445", "Here — this line. This is the one with a pulse."],
  ["scholar", "c5f56a6cc2ec4fa8920cb4c5889a3fb7", "This is asserted, not demonstrated. What is the evidence?"],
  ["editor",  "3274bdf8143c4378a2cb779582d26364", "Two 'however's in one paragraph. Pick one. Cut the other."],
  ["reader",  "125d6460953a443d8c65909adf87ca3f", "I followed you for two paragraphs, then I lost the thread."],
];
for (const [who, id, line] of picks) {
  const res = await fetch("https://api.fish.audio/v1/tts", {
    method: "POST",
    headers: { authorization: `Bearer ${key}`, "content-type": "application/json", model: "s2.1-pro-free" },
    body: JSON.stringify({ text: line, format: "mp3", reference_id: id }),
  });
  if (!res.ok) { console.log(who, "FAIL", res.status, (await res.text()).slice(0, 120)); continue; }
  const buf = await res.arrayBuffer();
  await Bun.write(`/tmp/voice_${who}.mp3`, buf);
  console.log(who.padEnd(8), "ok", String(buf.byteLength).padStart(7), "bytes");
}
EOF
